#!/bin/bash
# Trinity Compress Installer (Bash)
# Installs Trinity Compress assets into the current repository

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(dirname "$SCRIPT_DIR")"

echo "Installing Trinity Compress..."

# Check if files already exist
if [[ -f "$REPO_ROOT/trinity-compress.config.json" ]]; then
    echo "Config already exists: trinity-compress.config.json"
else
    echo "Error: Config file not found. Run from the repository root."
    exit 1
fi

if [[ -f "$SCRIPT_DIR/trinity-compress.sh" ]]; then
    echo "Compression script already exists: scripts/trinity-compress.sh"
else
    echo "Error: Compression script not found."
    exit 1
fi

# Ensure script is executable
chmod +x "$SCRIPT_DIR/trinity-compress.sh"
echo "Made trinity-compress.sh executable"

# Add .gitignore entry if not present
if [[ -f "$REPO_ROOT/.gitignore" ]]; then
    if ! grep -q "*.bak" "$REPO_ROOT/.gitignore"; then
        echo "" >> "$REPO_ROOT/.gitignore"
        echo "# Trinity Compress backups" >> "$REPO_ROOT/.gitignore"
        echo "*.bak" >> "$REPO_ROOT/.gitignore"
        echo "Added *.bak to .gitignore"
    else
        echo "*.bak already in .gitignore"
    fi
else
    echo "# Trinity Compress backups" > "$REPO_ROOT/.gitignore"
    echo "*.bak" >> "$REPO_ROOT/.gitignore"
    echo "Created .gitignore with *.bak rule"
fi

# Create Makefile if not present
if [[ ! -f "$REPO_ROOT/Makefile" ]]; then
    cat > "$REPO_ROOT/Makefile" << 'MAKEFILE'
.PHONY: optimize-prompts optimize-undo help

help:
	@echo "Trinity Compress Makefile targets:"
	@echo "  optimize-prompts  - Compress prompts (balanced mode)"
	@echo "  optimize-prompts=<mode> - Compress with specific mode (balanced|aggressive|light)"
	@echo "  optimize-undo     - Restore from last backup"

optimize-prompts:
	@bash scripts/trinity-compress.sh balanced

optimize-prompts-balanced:
	@bash scripts/trinity-compress.sh balanced

optimize-prompts-aggressive:
	@bash scripts/trinity-compress.sh aggressive

optimize-prompts-light:
	@bash scripts/trinity-compress.sh light

optimize-undo:
	@bash scripts/trinity-compress.sh undo
MAKEFILE
    echo "Created Makefile with Trinity Compress targets"
else
    echo "Makefile already exists"
fi

