echo "  bash scripts/trinity-compress.sh aggressive"
echo "  bash scripts/trinity-compress.sh light"
echo "  bash scripts/trinity-compress.sh undo"
echo ""
echo "Or via Makefile:"
echo "  make optimize-prompts"
echo "  make optimize-undo"
EOF\n",
