      "keystrokes": "cat > scripts/install.ps1 << 'EOF'
# Trinity Compress Installer (PowerShell)
# Installs Trinity Compress assets into the current repository

$ErrorActionPreference = "Stop"

$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$repoRoot = Split-Path -Parent $scriptDir

Write-Host "Installing Trinity Compress..."

# Check if files already exist
$configFile = Join-Path $repoRoot "trinity-compress.config.json"
$compressScript = Join-Path $scriptDir "trinity-compress.sh"

if (Test-Path $configFile) {
    Write-Host "Config already exists: trinity-compress.config.json"
} else {
    Write-Host "Error: Config file not found. Run from the repository root." -ForegroundColor Red
    exit 1
}

if (Test-Path $compressScript) {
    Write-Host "Compression script already exists: scripts/trinity-compress.sh"
} else {
    Write-Host "Error: Compression script not found." -ForegroundColor Red
    exit 1
}

# Ensure script is executable (for Git Bash/WSL)
Write-Host "Script ready: trinity-compress.sh"

# Add .gitignore entry if not present
$gitignore = Join-Path $repoRoot ".gitignore"
if (Test-Path $gitignore) {
    $content = Get-Content $gitignore -Raw
    if ($content -notmatch "\\*\.bak") {
        Add-Content $gitignore ""
        Add-Content $gitignore "# Trinity Compress backups"
        Add-Content $gitignore "*.bak"
        Write-Host "Added *.bak to .gitignore"
    } else {
        Write-Host "*.bak already in .gitignore"
    }
} else {
    Add-Content $gitignore "# Trinity Compress backups"
    Add-Content $gitignore "*.bak"
    Write-Host "Created .gitignore with *.bak rule"
}

# Create Makefile if not present
$makefile = Join-Path $repoRoot "Makefile"
if (-not (Test-Path $makefile)) {
    $makefileContent = @"
.PHONY: optimize-prompts optimize-undo help

help:
	@echo "Trinity Compress Makefile targets:"
	@echo "  optimize-prompts  - Compress prompts (balanced mode)"
	@echo "  optimize-prompts=<mode> - Compress with specific mode (balanced|aggressive|light)"
