	@bash scripts/trinity-compress.sh aggressive

optimize-prompts-light:
	@bash scripts/trinity-compress.sh light

optimize-undo:
	@bash scripts/trinity-compress.sh undo
"@
    Set-Content $makefile $makefileContent -NoNewline
    Write-Host "Created Makefile with Trinity Compress targets"
} else {
    Write-Host "Makefile already exists"
}

