Write-Host ""
Write-Host "Usage:"
Write-Host "  bash scripts/trinity-compress.sh balanced"
Write-Host "  bash scripts/trinity-compress.sh aggressive"
Write-Host "  bash scripts/trinity-compress.sh light"
Write-Host "  bash scripts/trinity-compress.sh undo"
Write-Host ""
Write-Host "Or via Makefile:"
Write-Host "  make optimize-prompts"
Write-Host "  make optimize-undo"
EOF\n",
